mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM
        folder_acl_tb
    WHERE
        folder_id = #{folderId}
    AND
        subject_user_id = #{userId}
    AND
        effect_type = #{effectType}
    AND
        status = #{status}
)

SELECT *
FROM folder_acl_tb
WHERE folder_id = #{folderId}
AND status = #{status}
AND effect_type = #{effectType}
AND (
subject_user_id = #{userId}

    OR subject_team_id = #{teamId}

)
ORDER BY permission_bit_mask DESC, acl_id DESC
LIMIT 1
